import type { ContractType } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface ContractTypeEntry {
  name: string;
  variant: BadgeVariants;
}

export const contractTypeConfig: Record<ContractType, ContractTypeEntry> = {
  assignment: { name: 'Assignment', variant: 'default' },
  w9: { name: 'W-9', variant: 'info' },
};

export const contractTypeItems: SelectItem<ContractType>[] = Object.entries(contractTypeConfig).map(
  ([value, { name }]) => ({ value: value as ContractType, name })
);

const defaultContractType: ContractTypeEntry = { name: '', variant: 'default' };

export function getContractTypeLabel(type: ContractType): ContractTypeEntry {
  return contractTypeConfig[type] ?? { ...defaultContractType, name: snakeCaseToCapitalizedCase(type) };
}
